import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getCurrentUser, getUserSessions, logout } from '../utils/api';
import { ParticleBackground } from '../components/ParticleBackground';

// Companion data
const companionsData = {
  'omkar_ai': { 
    id: 'omkar_ai', 
    name: 'Omkar', 
    subject: 'AI & ML', 
    avatar: '🧑‍💻',
    description: 'Expert in Artificial Intelligence and Machine Learning',
    color: 'from-blue-500 to-cyan-500'
  },
  'priya_biology': { 
    id: 'priya_biology', 
    name: 'Priya', 
    subject: 'Biology', 
    avatar: '👩‍🔬',
    description: 'Passionate Biology tutor specializing in life sciences',
    color: 'from-green-500 to-emerald-500'
  }
};

export const Dashboard = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedTutor, setSelectedTutor] = useState(null);

  useEffect(() => {
    loadUserData();
  }, []);

  const loadUserData = async () => {
    try {
      const currentUser = getCurrentUser();
      setUser(currentUser);

      // Load session history
      const userSessions = await getUserSessions();
      setSessions(userSessions);
    } catch (error) {
      console.error('❌ Error loading user data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  const handleStartNewSession = (companion) => {
    const userId = localStorage.getItem('userId') || `user_${Date.now()}`;
    localStorage.setItem('userId', userId);

    // Generate new room ID
    const roomId = `room_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;

    navigate(`/video/${roomId}?companion=${companion.id}`, {
      state: { companion, userId, roomId }
    });
  };

  const handleContinueSession = (session) => {
    const companion = companionsData[session.tutor_id] || companionsData['omkar_ai'];
    const userId = localStorage.getItem('userId') || `user_${Date.now()}`;

    navigate(`/video/${session.session_id}?companion=${session.tutor_id}`, {
      state: { companion, userId, roomId: session.session_id }
    });
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffInMs = now - date;
    const diffInMins = Math.floor(diffInMs / 60000);
    const diffInHours = Math.floor(diffInMs / 3600000);
    const diffInDays = Math.floor(diffInMs / 86400000);

    if (diffInMins < 1) return 'Just now';
    if (diffInMins < 60) return `${diffInMins} min ago`;
    if (diffInHours < 24) return `${diffInHours}h ago`;
    if (diffInDays < 7) return `${diffInDays}d ago`;
    return date.toLocaleDateString();
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-900 via-purple-900 to-pink-900 flex items-center justify-center">
        <div className="text-white text-xl">Loading...</div>
      </div>
    );
  }

  return (
    <div className="relative min-h-screen bg-gradient-to-br from-indigo-900 via-purple-900 to-pink-900 text-white overflow-hidden">
      <ParticleBackground />

      <div className="relative z-10">
        {/* Header */}
        <div className="border-b border-white/10 bg-black/20 backdrop-blur-sm">
          <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <h1 className="text-2xl font-bold">
                <span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-400 via-purple-400 to-pink-400">
                  Saarthi
                </span>
              </h1>
              <div className="h-6 w-px bg-white/20" />
              <span className="text-gray-300">Dashboard</span>
            </div>

            <div className="flex items-center gap-4">
              <div className="text-right">
                <p className="text-sm text-gray-300">Welcome back,</p>
                <p className="font-semibold">{user?.name || 'User'}</p>
              </div>
              <button
                onClick={handleLogout}
                className="px-4 py-2 bg-white/10 hover:bg-white/20 rounded-lg transition-all duration-300 text-sm font-medium"
              >
                Logout
              </button>
            </div>
          </div>
        </div>

        <div className="max-w-7xl mx-auto px-6 py-8">
          {/* Stats Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
            <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
              <div className="text-3xl mb-2">📚</div>
              <div className="text-3xl font-bold mb-1">{sessions.length}</div>
              <div className="text-sm text-gray-300">Total Sessions</div>
            </div>

            <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
              <div className="text-3xl mb-2">💬</div>
              <div className="text-3xl font-bold mb-1">
                {sessions.reduce((sum, s) => sum + (s.message_count || 0), 0)}
              </div>
              <div className="text-sm text-gray-300">Messages Sent</div>
            </div>

            <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
              <div className="text-3xl mb-2">🎯</div>
              <div className="text-3xl font-bold mb-1">2</div>
              <div className="text-sm text-gray-300">AI Tutors</div>
            </div>
          </div>

          {/* Main Content */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Left: Session History (ChatGPT-style) */}
            <div className="lg:col-span-2">
              <h2 className="text-2xl font-bold mb-4">Your Learning Sessions</h2>

              {sessions.length === 0 ? (
                <div className="bg-white/10 backdrop-blur-lg rounded-xl p-12 border border-white/20 text-center">
                  <div className="text-6xl mb-4">📝</div>
                  <h3 className="text-xl font-semibold mb-2">No sessions yet</h3>
                  <p className="text-gray-300 mb-6">Start your first learning session with an AI tutor!</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {sessions.map((session) => {
                    const companion = companionsData[session.tutor_id] || companionsData['omkar_ai'];
                    return (
                      <button
                        key={session.id}
                        onClick={() => handleContinueSession(session)}
                        className="w-full bg-white/10 backdrop-blur-lg rounded-xl p-4 border border-white/20 hover:bg-white/20 transition-all duration-300 text-left group"
                      >
                        <div className="flex items-center gap-4">
                          <div className="text-4xl">{companion.avatar}</div>
                          <div className="flex-1">
                            <div className="flex items-center justify-between mb-1">
                              <h3 className="font-semibold text-lg group-hover:text-blue-300 transition-colors">
                                {companion.name} - {session.subject || companion.subject}
                              </h3>
                              <span className="text-xs text-gray-400">
                                {formatDate(session.last_active)}
                              </span>
                            </div>
                            <div className="flex items-center gap-4 text-sm text-gray-300">
                              <span>💬 {session.message_count || 0} messages</span>
                              <span>•</span>
                              <span>📅 {new Date(session.created_at).toLocaleDateString()}</span>
                            </div>
                          </div>
                          <div className="text-gray-400 group-hover:text-white transition-colors">
                            →
                          </div>
                        </div>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Right: Tutor Selection */}
            <div>
              <h2 className="text-2xl font-bold mb-4">Select a Tutor</h2>

              <div className="space-y-4">
                {Object.values(companionsData).map((companion) => (
                  <div
                    key={companion.id}
                    className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20 hover:bg-white/20 transition-all duration-300"
                  >
                    <div className="text-5xl mb-3 text-center">{companion.avatar}</div>
                    <h3 className="text-xl font-bold text-center mb-2">{companion.name}</h3>
                    <p className="text-sm text-center text-gray-300 mb-1">{companion.subject}</p>
                    <p className="text-xs text-center text-gray-400 mb-4">{companion.description}</p>

                    <button
                      onClick={() => handleStartNewSession(companion)}
                      className={`w-full py-3 bg-gradient-to-r ${companion.color} rounded-lg font-semibold hover:scale-105 transform transition-all duration-300 shadow-lg`}
                    >
                      Start New Session
                    </button>
                  </div>
                ))}
              </div>

              {/* Quick Actions */}
              <div className="mt-6 bg-white/5 backdrop-blur-sm rounded-xl p-4 border border-white/10">
                <h3 className="font-semibold mb-3 text-sm text-gray-300">Quick Actions</h3>
                <div className="space-y-2 text-sm">
                  <button className="w-full text-left px-3 py-2 hover:bg-white/10 rounded-lg transition-all">
                    📊 View Analytics
                  </button>
                  <button className="w-full text-left px-3 py-2 hover:bg-white/10 rounded-lg transition-all">
                    ⚙️ Settings
                  </button>
                  <button className="w-full text-left px-3 py-2 hover:bg-white/10 rounded-lg transition-all">
                    💡 Give Feedback
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
